function validate(input) {
  const [{ Orders = [] }] = input;
  if (Orders.length % 6 !== 0) return 'The number of rows must be a multiple of 6.';
  const seen = new Set();
  for (const [minute, count] of Orders) {
    if (minute === null || count === null) return 'minute and order_count cannot be null.';
    if (minute < 1 || minute > Orders.length) return `minute ${minute} is outside 1..${Orders.length}.`;
    if (seen.has(minute)) return `minute ${minute} appears twice.`;
    if (count < 0) return 'order_count cannot be negative.';
    seen.add(minute);
  }
  return null;
}

