function generate(rand, size) {
  const intervals = size === 'small' ? Math.floor(rand() * 3) : 300 + Math.floor(rand() * 30);
  const top = size === 'small' ? 7 : 1000;
  const Orders = [];
  for (let minute = 1; minute <= intervals * 6; minute++) Orders.push([minute, Math.floor(rand() * top)]);
  // Shuffle so that the input order never hands out the answer's order.
  for (let i = Orders.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Orders[i], Orders[j]] = [Orders[j], Orders[i]];
  }
  return [{ Orders }];
}
